package com.shopstream.catalog;

import java.math.BigDecimal;
import java.util.Collection;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import org.springframework.stereotype.Repository;

@Repository
public class SlowProductRepository implements ProductRepository {

    private final Map<String, Product> table = new ConcurrentHashMap<>();
    private final AtomicInteger loads = new AtomicInteger();
    private final long latencyMs;

    public SlowProductRepository(CatalogProperties props) {
        this.latencyMs = props.dbLatencyMs();
        for (int i = 1; i <= props.seedProducts(); i++) {
            String id = "p-" + i;
            table.put(id, new Product(id, "Product " + i, BigDecimal.valueOf(i * 3L, 2), 100));
        }
    }

    @Override
    public Optional<Product> findById(String id) {
        loads.incrementAndGet();
        try {
            Thread.sleep(latencyMs);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return Optional.ofNullable(table.get(id));
    }

    @Override
    public void save(Product product) {
        table.put(product.id(), product);
    }

    @Override
    public Collection<String> allIds() {
        return table.keySet();
    }

    @Override
    public int loadCount() {
        return loads.get();
    }
}

