package com.shopstream.catalog;

import java.util.List;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.stereotype.Component;

@Component
public class BloomFilter {

    static final String KEY = "bf:product:ids";

    // BF.RESERVE fails with "item exists" when the key exists, so ignore that error.
    private static final DefaultRedisScript<Long> RESERVE = new DefaultRedisScript<>("""
            pcall(redis.call, 'BF.RESERVE', KEYS[1], ARGV[1], ARGV[2])
            return 1
            """, Long.class);

    private static final DefaultRedisScript<Long> ADD = new DefaultRedisScript<>(
            "return redis.call('BF.ADD', KEYS[1], ARGV[1])", Long.class);

    private static final DefaultRedisScript<Long> EXISTS = new DefaultRedisScript<>(
            "return redis.call('BF.EXISTS', KEYS[1], ARGV[1])", Long.class);

    private final StringRedisTemplate redis;

    public BloomFilter(StringRedisTemplate redis) {
        this.redis = redis;
    }

    /** Create the filter sized for 'capacity' ids at the given false-positive rate. */
    public void reserve(double errorRate, long capacity) {
        redis.execute(RESERVE, List.of(KEY), String.valueOf(errorRate), String.valueOf(capacity));
    }

    public void add(String id) {
        redis.execute(ADD, List.of(KEY), id);
    }

    public boolean mightContain(String id) {
        Long r = redis.execute(EXISTS, List.of(KEY), id);
        return r != null && r == 1L;
    }
}

package com.shopstream.catalog;

import java.time.Duration;
import java.util.List;
import java.util.UUID;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.stereotype.Component;

@Component
public class SingleFlightLock {

    // Delete the lock only if we still own it (compare token, then delete, atomically).
    private static final DefaultRedisScript<Long> RELEASE = new DefaultRedisScript<>("""
            if redis.call('GET', KEYS[1]) == ARGV[1] then
              return redis.call('DEL', KEYS[1])
            end
            return 0
            """, Long.class);

    private final StringRedisTemplate redis;
    private final Duration ttl;

    public SingleFlightLock(StringRedisTemplate redis, CatalogProperties props) {
        this.redis = redis;
        this.ttl = props.lockTtl();
    }

    /** Returns an owner token if we got the lock, otherwise null. */
    public String tryAcquire(String productId) {
        String token = UUID.randomUUID().toString();
        Boolean ok = redis.opsForValue().setIfAbsent(key(productId), token, ttl);
        return Boolean.TRUE.equals(ok) ? token : null;
    }

    public void release(String productId, String token) {
        redis.execute(RELEASE, List.of(key(productId)), token);
    }

    private static String key(String productId) {
        return "lock:product:" + productId;
    }
}

package com.shopstream.catalog;

import java.time.Duration;
import java.util.Optional;
import java.util.concurrent.ThreadLocalRandom;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;
import tools.jackson.databind.json.JsonMapper;

@Component
public class ProductCache {

    static final String ABSENT = "__absent__";

    public enum Status { MISS, HIT, NEGATIVE }

    public record Lookup(Status status, Product product) {
        static final Lookup MISS = new Lookup(Status.MISS, null);
        static final Lookup NEGATIVE = new Lookup(Status.NEGATIVE, null);

        public Optional<Product> asOptional() {
            return Optional.ofNullable(product);
        }
    }

    private final StringRedisTemplate redis;
    private final JsonMapper json;
    private final CatalogProperties props;
    public ProductCache(StringRedisTemplate redis, JsonMapper json, CatalogProperties props) {
        this.redis = redis;
        this.json = json;
        this.props = props;
    }

    public Lookup get(String id) {
        String raw = redis.opsForValue().get(key(id));
        if (raw == null) {
            return Lookup.MISS;
        }
        if (ABSENT.equals(raw)) {
            return Lookup.NEGATIVE;
        }
        return new Lookup(Status.HIT, json.readValue(raw, Product.class));
    }

    public void put(Product product) {
        redis.opsForValue().set(key(product.id()), json.writeValueAsString(product),
                withJitter(props.ttl(), props.ttlJitter()));
    }

    public void putAbsent(String id) {
        redis.opsForValue().set(key(id), ABSENT, props.negativeTtl());
    }

    public void evict(String id) {
        redis.delete(key(id));
    }

    static Duration withJitter(Duration base, double fraction) {
        double factor = 1.0 + ThreadLocalRandom.current().nextDouble(-fraction, fraction);
        return Duration.ofMillis(Math.round(base.toMillis() * factor));
    }

    static String key(String id) {
        return "product:" + id;
    }
}

package com.shopstream.catalog;

import java.time.Duration;
import java.util.Optional;
import org.springframework.stereotype.Service;

@Service
public class CatalogService {

    private final ProductRepository repository;
    private final ProductCache cache;
    private final BloomFilter bloom;
    private final SingleFlightLock lock;
    private final CatalogMetrics metrics;
private final Duration waitMax;

public CatalogService(ProductRepository repository, ProductCache cache, BloomFilter bloom,
                      SingleFlightLock lock, CatalogMetrics metrics, CatalogProperties props) {
    this.repository = repository;
    this.cache = cache;
    this.bloom = bloom;
    this.lock = lock;
    this.metrics = metrics;
    this.waitMax = props.waitMax();
}

public Optional<Product> find(String id) {
    if (!bloom.mightContain(id)) {
        metrics.result("bloom_reject");
        return Optional.empty();
    }
    ProductCache.Lookup first = cache.get(id);
    if (first.status() != ProductCache.Status.MISS) {
        metrics.result(first.status() == ProductCache.Status.HIT ? "hit" : "negative");
        return first.asOptional();
    }
    metrics.result("miss");
    return loadOnce(id);
}

private Optional<Product> loadOnce(String id) {
    String token = lock.tryAcquire(id);
    if (token != null) {
        try {
            ProductCache.Lookup again = cache.get(id);   // someone may have filled it
            if (again.status() != ProductCache.Status.MISS) {
                return again.asOptional();
            }
            return loadFromDatabase(id);
        } finally {
            lock.release(id, token);
        }
    }
    return waitForOwner(id);
}

private Optional<Product> waitForOwner(String id) {
    long deadline = System.nanoTime() + waitMax.toNanos();
    while (System.nanoTime() < deadline) {
        try {
            Thread.sleep(20);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            break;
        }
        ProductCache.Lookup l = cache.get(id);
        if (l.status() != ProductCache.Status.MISS) {
            return l.asOptional();
        }
    }
    return loadFromDatabase(id);          // owner was too slow or died: do the work ourselves
}

private Optional<Product> loadFromDatabase(String id) {
    Optional<Product> found = metrics.timeDbLoad(() -> repository.findById(id));
    if (found.isPresent()) {
        cache.put(found.get());
    } else {
        cache.putAbsent(id);
    }
    return found;
}

public Product save(Product product) {
    repository.save(product);
    bloom.add(product.id());      // a new id must pass the filter
        cache.evict(product.id());    // delete after the write; the next read repopulates
        return product;
    }
}

