import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Timer;
import java.util.function.Supplier;
import org.springframework.stereotype.Component;

@Component
public class CatalogMetrics {

    private final MeterRegistry registry;
    private final Timer dbTimer;

    public CatalogMetrics(MeterRegistry registry) {
        this.registry = registry;
        this.dbTimer = Timer.builder("catalog.db.loads").register(registry);
    }

    public void result(String kind) {
        registry.counter("catalog.cache", "result", kind).increment();
    }

    public <T> T timeDbLoad(Supplier<T> work) {
        return dbTimer.record(work);
    }
}

