import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.IntStream;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.annotation.Import;
import org.springframework.data.redis.core.StringRedisTemplate;
@SpringBootTest(properties = {"catalog.seed-products=50", "catalog.db-latency-ms=100"})
@Import(RedisTestConfig.class)
class CatalogServiceIT {

    @Autowired CatalogService service;
    @Autowired ProductRepository repository;
    @Autowired StringRedisTemplate redis;
    @Autowired BloomFilter bloom;

    @Test
    void secondReadIsServedFromCache() {
        int before = repository.loadCount();
        assertThat(service.find("p-1")).isPresent();
        assertThat(service.find("p-1")).isPresent();
        assertThat(repository.loadCount() - before).isEqualTo(1);
        Long ttl = redis.getExpire("product:p-1");
        assertThat(ttl).isBetween(470L, 730L);        // 600 s plus or minus 20 percent
    }

    @Test
    void unknownIdNeverReachesTheDatabase() {
        int before = repository.loadCount();
        assertThat(service.find("does-not-exist-" + System.nanoTime())).isEmpty();
        assertThat(repository.loadCount()).isEqualTo(before);
    }

    @Test
    void concurrentMissesCauseOneDatabaseLoad() {
        redis.delete("product:p-7");
        int before = repository.loadCount();
        ExecutorService pool = Executors.newFixedThreadPool(40);
        try {
            List<CompletableFuture<Boolean>> calls = IntStream.range(0, 40)
                    .mapToObj(i -> CompletableFuture.supplyAsync(
                            () -> service.find("p-7").isPresent(), pool))
                    .toList();
            calls.forEach(c -> assertThat(c.join()).isTrue());
        } finally {
            pool.shutdown();
        }
        assertThat(repository.loadCount() - before).isEqualTo(1);
    }

    @Test
    void removedProductIsRememberedAsAbsent() {
        // An id that is in the Bloom filter but not in the table: add it to the filter only.
        String ghost = "ghost-" + System.nanoTime();
        bloom.add(ghost);
        int before = repository.loadCount();
        assertThat(service.find(ghost)).isEmpty();
        assertThat(service.find(ghost)).isEmpty();
        assertThat(repository.loadCount() - before).isEqualTo(1);
        assertThat(redis.opsForValue().get("product:" + ghost)).isEqualTo("__absent__");
    }
}

