import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.stereotype.Component;

@Component
public class TokenBucketLimiter {

    public record Decision(boolean allowed, long remaining, long retryAfterMs, long fullInMs) {
    }

    private final StringRedisTemplate redis;
    private final DefaultRedisScript<List> script = new DefaultRedisScript<>();

    public TokenBucketLimiter(StringRedisTemplate redis) {
        this.redis = redis;
        script.setLocation(new ClassPathResource("scripts/token_bucket.lua"));
        script.setResultType(List.class);
    }

    public Decision tryAcquire(String identity, RateLimitProperties.Plan plan, int cost) {
        @SuppressWarnings("unchecked")
        List<Long> r = (List<Long>) redis.execute(script, List.of("rl:" + identity),
                String.valueOf(plan.capacity()),
                String.valueOf(plan.refillPerSecond()),
                String.valueOf(cost));
        return new Decision(r.get(0) == 1L, r.get(1), r.get(2), r.get(3));
    }
}

package com.shopstream.ratelimit;

import io.micrometer.core.instrument.MeterRegistry;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.DataAccessException;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;

@Component
public class RateLimitInterceptor implements HandlerInterceptor {

    private static final Logger log = LoggerFactory.getLogger(RateLimitInterceptor.class);

    private final TokenBucketLimiter limiter;
    private final RateLimitProperties props;
    private final MeterRegistry metrics;

    public RateLimitInterceptor(TokenBucketLimiter limiter, RateLimitProperties props,
                                MeterRegistry metrics) {
        this.limiter = limiter;
        this.props = props;
        this.metrics = metrics;
    }
    @Override
    public boolean preHandle(HttpServletRequest req, HttpServletResponse resp, Object handler)
            throws Exception {
        String apiKey = req.getHeader("X-API-Key");
        String identity;
        String planName;
        if (apiKey == null) {
            identity = "ip:" + req.getRemoteAddr();
            planName = "anonymous";
        } else {
            planName = props.keys().get(apiKey);
            if (planName == null) {
                resp.sendError(HttpServletResponse.SC_UNAUTHORIZED, "Unknown API key");
                return false;
            }
            identity = "key:" + apiKey;
        }
        RateLimitProperties.Plan plan = props.plans().get(planName);
        int cost = props.routeCosts().getOrDefault(req.getRequestURI(), 1);

        TokenBucketLimiter.Decision d;
        try {
            d = limiter.tryAcquire(identity, plan, cost);
        } catch (DataAccessException e) {
            metrics.counter("ratelimit.errors").increment();
            log.warn("Rate limiter unavailable: {}", e.toString());
            if (props.failOpen()) {
                return true;
            }
            resp.sendError(HttpServletResponse.SC_SERVICE_UNAVAILABLE, "Rate limiter unavailable");
            return false;
        }

        resp.setHeader("X-RateLimit-Limit", String.valueOf(plan.capacity()));
        resp.setHeader("X-RateLimit-Remaining", String.valueOf(d.remaining()));
        if (d.allowed()) {
            metrics.counter("ratelimit.requests", "plan", planName, "result", "allowed")
                    .increment();
            return true;
        }
        long retryAfterSeconds = Math.max(1, (d.retryAfterMs() + 999) / 1000);
        resp.setHeader("Retry-After", String.valueOf(retryAfterSeconds));
        resp.setStatus(429);
        resp.setContentType("application/json");
        resp.getWriter().write(
                "{\"error\":\"rate_limited\",\"retryAfterMs\":" + d.retryAfterMs() + "}");
        metrics.counter("ratelimit.requests", "plan", planName, "result", "denied")
                .increment();
        return false;
    }
}

