import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.annotation.Import;

@SpringBootTest(
        webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT,
        properties = {
            "ratelimit.plans.tiny.capacity=5",
            "ratelimit.plans.tiny.refill-per-second=0.001",
            "ratelimit.plans.quick.capacity=2",
            "ratelimit.plans.quick.refill-per-second=20",
            "ratelimit.keys.k-tiny=tiny"
        })
@Import(RedisTestConfig.class)
class RateLimiterIT {

    @Value("${local.server.port}") int port;
    @Autowired TokenBucketLimiter limiter;
    @Autowired RateLimitProperties props;

    @Test
    void bucketAllowsCapacityThenDenies() {
        var plan = props.plans().get("tiny");
        for (int i = 0; i < 5; i++) {
            assertThat(limiter.tryAcquire("t:basic", plan, 1).allowed()).isTrue();
        }
        var denied = limiter.tryAcquire("t:basic", plan, 1);
        assertThat(denied.allowed()).isFalse();
        assertThat(denied.retryAfterMs()).isPositive();
    }

    @Test
    void bucketRefillsOverTime() throws Exception {
        var plan = props.plans().get("quick");              // 20 tokens per second
        limiter.tryAcquire("t:refill", plan, 1);
        limiter.tryAcquire("t:refill", plan, 1);
        assertThat(limiter.tryAcquire("t:refill", plan, 1).allowed()).isFalse();
        Thread.sleep(150);                                   // about 3 tokens, capped at 2
        assertThat(limiter.tryAcquire("t:refill", plan, 1).allowed()).isTrue();
    }

    @Test
    void concurrentCallersNeverExceedCapacity() {
        var plan = props.plans().get("tiny");               // 5 tokens, practically no refill
        AtomicInteger allowed = new AtomicInteger();
        ExecutorService pool = Executors.newFixedThreadPool(32);
        try {
            List<CompletableFuture<Void>> calls = new ArrayList<>();
            for (int i = 0; i < 200; i++) {
                calls.add(CompletableFuture.runAsync(() -> {
                    if (limiter.tryAcquire("t:race", plan, 1).allowed()) {
                        allowed.incrementAndGet();
                    }
                }, pool));
            }
            calls.forEach(CompletableFuture::join);
        } finally {
            pool.shutdown();
        }
        assertThat(allowed.get()).isEqualTo(5);
    }

    @Test
    void httpContractIncludesHeadersAnd429() throws Exception {
        HttpClient http = HttpClient.newHttpClient();
        URI uri = URI.create("http://localhost:" + port + "/api/ping");
        HttpRequest req = HttpRequest.newBuilder(uri)
                .header("X-API-Key", "k-tiny").build();
        HttpResponse<String> last = null;
        for (int i = 0; i < 6; i++) {
            last = http.send(req, HttpResponse.BodyHandlers.ofString());
        }
        assertThat(last.statusCode()).isEqualTo(429);
        assertThat(last.headers().firstValue("Retry-After")).isPresent();
        assertThat(last.headers().firstValue("X-RateLimit-Remaining")).hasValue("0");
    }
}

