    private final StringRedisTemplate redis;
    private final SaleProperties props;
    private final DefaultRedisScript<List> reserve = script("reserve");
    private final DefaultRedisScript<Long> confirm = longScript("confirm");
    private final DefaultRedisScript<Long> release = longScript("release");

    public ReservationService(StringRedisTemplate redis, SaleProperties props) {
        this.redis = redis;
        this.props = props;
    }

    private static DefaultRedisScript<List> script(String name) {
        var s = new DefaultRedisScript<List>();
        s.setLocation(new ClassPathResource("scripts/" + name + ".lua"));
        s.setResultType(List.class);
        return s;
    }

    private static DefaultRedisScript<Long> longScript(String name) {
        var s = new DefaultRedisScript<Long>();
        s.setLocation(new ClassPathResource("scripts/" + name + ".lua"));
        s.setResultType(Long.class);
        return s;
    }

    /** (Re)opens a sale with the given stock. Resets buyers and pending holds. */
    public void openSale(String sku, int units) {
        redis.delete(List.of("buyers:" + sku, "resvexp:" + sku));
        redis.opsForValue().set("stock:" + sku, String.valueOf(units));
        redis.opsForSet().add("sales:active", sku);
    }

    public long stock(String sku) {
        String v = redis.opsForValue().get("stock:" + sku);
        return v == null ? 0 : Long.parseLong(v);
    }

    public Set<String> activeSales() {
        Set<String> s = redis.opsForSet().members("sales:active");
        return s == null ? Set.of() : s;
    }

    public Reservation reserve(String sku, String userId, int qty, String idempotencyKey) {
        String id = UUID.randomUUID().toString();
        String idem = idempotencyKey != null ? idempotencyKey : id;
        @SuppressWarnings("unchecked")
        List<Object> r = (List<Object>) redis.execute(reserve,
                List.of("stock:" + sku, "buyers:" + sku, "resvexp:" + sku,
                        "resv:" + sku + ":" + id, "idem:" + sku + ":" + idem),
                id, userId, String.valueOf(qty), String.valueOf(props.hold().toMillis()));
        long code = (Long) r.get(0);
        String reservationId = (String) r.get(1);
        Outcome outcome = switch ((int) code) {
            case 1 -> Outcome.RESERVED;
            case 3 -> Outcome.DUPLICATE_REQUEST;
            case -1 -> Outcome.ALREADY_BOUGHT;
            case -2 -> Outcome.SOLD_OUT;
            default -> Outcome.NO_SUCH_SALE;
        };
        return new Reservation(outcome, reservationId);
    }

    public ConfirmOutcome confirm(String sku, String reservationId) {
        Long r = redis.execute(confirm,
                List.of("resvexp:" + sku, "resv:" + sku + ":" + reservationId, props.stream()),
                reservationId, sku);
        return r == null || r == 0 ? ConfirmOutcome.EXPIRED
                : r == 1 ? ConfirmOutcome.CONFIRMED : ConfirmOutcome.ALREADY_CONFIRMED;
    }

    /** Called by the reaper. Returns how many reservations had their stock returned. */
    public int releaseExpired(String sku) {
        long horizon = System.currentTimeMillis() + 1000;      // script re-checks with Redis TIME
        Set<String> due = redis.opsForZSet().rangeByScore("resvexp:" + sku, 0, horizon, 0, 100);
        int released = 0;
        if (due == null) {
            return 0;
        }
        for (String id : due) {
            Long r = redis.execute(release,
                    List.of("stock:" + sku, "buyers:" + sku, "resvexp:" + sku,
                            "resv:" + sku + ":" + id), id);
            if (r != null && r == 1L) {
                released++;
            }
        }
        return released;
    }
}

