@RestController
@RequestMapping("/api/sales/{sku}")
public class SaleController {

    public record ReserveRequest(String userId, int qty) {
    }

    private final ReservationService service;

    public SaleController(ReservationService service) {
        this.service = service;
    }

    @PostMapping
    public Map<String, Object> open(@PathVariable String sku, @RequestParam int stock) {
        service.openSale(sku, stock);
        return Map.of("sku", sku, "stock", stock);
    }

    @GetMapping
    public Map<String, Object> state(@PathVariable String sku) {
        return Map.of("sku", sku, "stock", service.stock(sku));
    }

    @PostMapping("/reservations")
    public ResponseEntity<Map<String, Object>> reserve(
            @PathVariable String sku, @RequestBody ReserveRequest body,
            @RequestHeader(value = "Idempotency-Key", required = false) String key) {
        if (body.userId() == null || body.qty() < 1 || body.qty() > 2) {
            return ResponseEntity.badRequest().body(Map.of("error", "invalid_request"));
        }
        var r = service.reserve(sku, body.userId(), body.qty(), key);
        return switch (r.outcome()) {
            case RESERVED -> ResponseEntity.status(201)
                    .body(Map.of("reservationId", r.reservationId()));
            case DUPLICATE_REQUEST -> ResponseEntity.ok(Map.of("reservationId", r.reservationId()));
            case ALREADY_BOUGHT -> ResponseEntity.status(409)
                    .body(Map.of("error", "already_bought"));
            case SOLD_OUT -> ResponseEntity.status(409).body(Map.of("error", "sold_out"));
            case NO_SUCH_SALE -> ResponseEntity.status(404).body(Map.of("error", "no_such_sale"));
        };
    }

    @PostMapping("/reservations/{id}/confirm")
    public ResponseEntity<Map<String, Object>> confirm(@PathVariable String sku,
                                                       @PathVariable String id) {
        return switch (service.confirm(sku, id)) {
            case CONFIRMED, ALREADY_CONFIRMED -> ResponseEntity.ok(Map.of("status", "PAID"));
            case EXPIRED -> ResponseEntity.status(410).body(Map.of("error", "reservation_expired"));
        };
    }
}

