package com.shopstream.flashsale;

import jakarta.annotation.PostConstruct;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.data.redis.RedisSystemException;
import org.springframework.data.redis.connection.stream.Consumer;
import org.springframework.data.redis.connection.stream.MapRecord;
import org.springframework.data.redis.connection.stream.ReadOffset;
import org.springframework.data.redis.connection.stream.StreamOffset;
import org.springframework.data.redis.connection.stream.StreamReadOptions;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
public class OrderWorker {

    private static final Logger log = LoggerFactory.getLogger(OrderWorker.class);

    private final StringRedisTemplate redis;
    private final SaleProperties props;
    private final OrderStore store;
    private final Consumer consumer;

    public OrderWorker(StringRedisTemplate redis, SaleProperties props, OrderStore store) {
        this.redis = redis;
        this.props = props;
        this.store = store;
        this.consumer = Consumer.from(props.group(), "worker-" + UUID.randomUUID());
    }

    @PostConstruct
    void createGroup() {
        try {
            redis.opsForStream().createGroup(props.stream(), ReadOffset.from("0"), props.group());
        } catch (RedisSystemException e) {
            String msg = String.valueOf(e.getMessage()) + e.getCause();
            if (!msg.contains("BUSYGROUP")) {
                throw e;           // any error other than "group already exists" is real
            }
        }
    }

    @Scheduled(fixedDelay = 200)
    public void poll() {
        // 1. entries delivered to this consumer earlier but never acknowledged (offset "0")
        handle(read(ReadOffset.from("0")));
        // 2. new entries nobody has received yet (">")
        handle(read(ReadOffset.lastConsumed()));
    }

    private List<MapRecord<String, Object, Object>> read(ReadOffset offset) {
        var options = StreamReadOptions.empty().count(50);
        return redis.opsForStream().read(consumer, options,
                StreamOffset.create(props.stream(), offset));
    }

    private void handle(List<MapRecord<String, Object, Object>> records) {
        if (records == null) {
            return;
        }
        for (var rec : records) {
            Map<Object, Object> f = rec.getValue();
            var order = new OrderStore.Order((String) f.get("orderId"), (String) f.get("sku"),
                    (String) f.get("user"), Integer.parseInt((String) f.get("qty")));
            if (!store.save(order)) {
                log.info("Order {} was already processed; acknowledging again", order.orderId());
            }
            redis.opsForStream().acknowledge(props.stream(), props.group(), rec.getId());
        }
    }
}

