package com.shopstream.flashsale;
import static org.assertj.core.api.Assertions.assertThat;
import static org.awaitility.Awaitility.await;
import java.time.Duration;
import java.util.List;
import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.stream.IntStream;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.annotation.Import;
import org.springframework.data.redis.core.StringRedisTemplate;

@SpringBootTest(properties = {"sale.hold=2s", "spring.task.scheduling.pool.size=2"})
@Import(RedisTestConfig.class)
class FlashSaleIT {

    @Autowired ReservationService service;
    @Autowired OrderStore orders;
    @Autowired StringRedisTemplate redis;

    @Test
    void neverOversells() throws Exception {
        service.openSale("race", 100);
        Queue<ReservationService.Reservation> results = new ConcurrentLinkedQueue<>();
        ExecutorService pool = Executors.newFixedThreadPool(64);
        try {
            List<Future<?>> futures = IntStream.range(0, 500)
                    .mapToObj(i -> pool.submit(
                            () -> results.add(service.reserve("race", "user-" + i, 1, null))))
                    .toList();
            for (Future<?> f : futures) {
                f.get();
            }
        } finally {
            pool.shutdown();
        }
        long reserved = results.stream()
                .filter(r -> r.outcome() == ReservationService.Outcome.RESERVED).count();
        long soldOut = results.stream()
                .filter(r -> r.outcome() == ReservationService.Outcome.SOLD_OUT).count();
        assertThat(reserved).isEqualTo(100);
        assertThat(soldOut).isEqualTo(400);
        assertThat(service.stock("race")).isZero();
    }

    @Test
    void sameIdempotencyKeyDoesNotSpendStockTwice() {
        service.openSale("idem", 5);
        var first = service.reserve("idem", "alice", 1, "req-123");
        var replay = service.reserve("idem", "alice", 1, "req-123");
        assertThat(first.outcome()).isEqualTo(ReservationService.Outcome.RESERVED);
        assertThat(replay.outcome()).isEqualTo(ReservationService.Outcome.DUPLICATE_REQUEST);
        assertThat(replay.reservationId()).isEqualTo(first.reservationId());
        assertThat(service.stock("idem")).isEqualTo(4);
    }

    @Test
    void oneUnitPerShopper() {
        service.openSale("once", 5);
        service.reserve("once", "bob", 1, null);
        assertThat(service.reserve("once", "bob", 1, null).outcome())
                .isEqualTo(ReservationService.Outcome.ALREADY_BOUGHT);
    }

    @Test
    void expiredHoldReturnsStockAndCannotBeConfirmed() throws Exception {
        service.openSale("hold", 1);
        var r = service.reserve("hold", "carol", 1, null);
        assertThat(service.stock("hold")).isZero();
        Thread.sleep(2300);                                     // hold is 2 s
        assertThat(service.confirm("hold", r.reservationId()))
                .isEqualTo(ReservationService.ConfirmOutcome.EXPIRED);
        service.releaseExpired("hold");       // the background reaper may have won; either is fine
        assertThat(service.stock("hold")).isEqualTo(1);
        var retry = service.reserve("hold", "carol", 1, null);  // carol may try again
        assertThat(retry.outcome()).isEqualTo(ReservationService.Outcome.RESERVED);
    }

    @Test
    void confirmedReservationsBecomeOrdersExactlyOnce() {
        service.openSale("order", 10);
        int before = orders.count();
        for (int i = 0; i < 10; i++) {
            var r = service.reserve("order", "buyer-" + i, 1, null);
            service.confirm("order", r.reservationId());
            service.confirm("order", r.reservationId());        // a retry must be harmless
        }
        await().atMost(Duration.ofSeconds(10))
                .untilAsserted(() -> assertThat(orders.count() - before).isEqualTo(10));
        var summary = redis.opsForStream().pending("stream:orders", "fulfilment");
        Long pending = summary.getTotalPendingMessages();
        assertThat(pending).isZero();
    }
}

package com.shopstream.leaderboard;

import java.time.Clock;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import org.springframework.core.io.ClassPathResource;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.ZSetOperations.TypedTuple;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.stereotype.Service;

@Service
public class ScoreService {

    public static final String STREAM = "stream:score-events";
    private static final long BOARD_TTL_SECONDS = 8L * 24 * 3600;

    public record Entry(long rank, String player, double score) {
    }

    public record ScoreResult(String player, double score, long oldRank, long newRank) {
    }

    private final StringRedisTemplate redis;
    private final Clock clock;
    private final DefaultRedisScript<List> script = new DefaultRedisScript<>();

    public ScoreService(StringRedisTemplate redis, Clock clock) {
        this.redis = redis;
        this.clock = clock;
        script.setLocation(new ClassPathResource("scripts/score.lua"));
        script.setResultType(List.class);
    }

    public ScoreResult addPoints(String player, long points) {
        LocalDate today = LocalDate.now(clock);
        @SuppressWarnings("unchecked")
        List<Object> r = (List<Object>) redis.execute(script,
                List.of(boardKey(today), uniqueKey(today), STREAM),
                player, String.valueOf(points), String.valueOf(BOARD_TTL_SECONDS));
        return new ScoreResult(player, Double.parseDouble((String) r.get(0)),
                (Long) r.get(1), (Long) r.get(2));
    }

    public List<Entry> top(int size) {
        String key = boardKey(LocalDate.now(clock));
        var tuples = redis.opsForZSet().reverseRangeWithScores(key, 0, size - 1);
        return toEntries(tuples, 1);
    }

    /** The player's rank (1-based) plus two neighbours above and below. */
    public Optional<List<Entry>> around(String player) {
        String key = boardKey(LocalDate.now(clock));
        Long rank = redis.opsForZSet().reverseRank(key, player);
        if (rank == null) {
            return Optional.empty();
        }
        long start = Math.max(0, rank - 2);
        var tuples = redis.opsForZSet().reverseRangeWithScores(key, start, rank + 2);
        return Optional.of(toEntries(tuples, start + 1));
    }

    public long uniquePlayersToday() {
        Long n = redis.opsForHyperLogLog().size(uniqueKey(LocalDate.now(clock)));
        return n == null ? 0 : n;
    }

    private static List<Entry> toEntries(Set<TypedTuple<String>> tuples, long firstRank) {
        List<Entry> out = new ArrayList<>();
        if (tuples == null) {
            return out;
        }
        long rank = firstRank;
        for (TypedTuple<String> t : tuples) {          // the returned Set keeps Redis order
            out.add(new Entry(rank++, t.getValue(), t.getScore() == null ? 0 : t.getScore()));
        }
        return out;
    }

    static String boardKey(LocalDate d) {
        return "lb:points:daily:" + d;
    }

    static String uniqueKey(LocalDate d) {
        return "uv:players:" + d;
    }
}

package com.shopstream.leaderboard;

import jakarta.annotation.PostConstruct;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.springframework.data.redis.RedisSystemException;
import org.springframework.data.redis.connection.stream.Consumer;
import org.springframework.data.redis.connection.stream.MapRecord;
import org.springframework.data.redis.connection.stream.ReadOffset;
import org.springframework.data.redis.connection.stream.StreamOffset;
import org.springframework.data.redis.connection.stream.StreamReadOptions;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import tools.jackson.databind.json.JsonMapper;

@Component
public class EventForwarder {

    static final String GROUP = "notifier";

    public record BoardEvent(String player, String score, int rank) {
    }

    public record Notification(String player, String message, int rank) {
    }

    private final StringRedisTemplate redis;
    private final JsonMapper json;
    private final Consumer consumer = Consumer.from(GROUP, "fwd-" + UUID.randomUUID());

    public EventForwarder(StringRedisTemplate redis, JsonMapper json) {
        this.redis = redis;
        this.json = json;
    }

    @PostConstruct
    void createGroup() {
        try {
            redis.opsForStream().createGroup(ScoreService.STREAM, ReadOffset.from("0"), GROUP);
        } catch (RedisSystemException e) {
            if (!(String.valueOf(e.getMessage()) + e.getCause()).contains("BUSYGROUP")) {
                throw e;
            }
        }
    }

    @Scheduled(fixedDelay = 100)
    public void poll() {
        forward(read(ReadOffset.from("0")));            // our own unacknowledged entries
        forward(read(ReadOffset.lastConsumed()));       // new entries
    }

    private List<MapRecord<String, Object, Object>> read(ReadOffset offset) {
        return redis.opsForStream().read(consumer, StreamReadOptions.empty().count(100),
                StreamOffset.create(ScoreService.STREAM, offset));
    }

    private void forward(List<MapRecord<String, Object, Object>> records) {
        if (records == null) {
            return;
        }
        for (var rec : records) {
            Map<Object, Object> f = rec.getValue();
            String player = (String) f.get("player");
            int oldRank = Integer.parseInt((String) f.get("oldRank"));
            int newRank = Integer.parseInt((String) f.get("newRank"));

            var board = new BoardEvent(player, (String) f.get("score"), newRank + 1);
            redis.convertAndSend("chan:board", json.writeValueAsString(board));

            String message = null;
            if (newRank == 0 && oldRank != 0) {
                message = "You took the lead!";
            } else if (newRank < 10 && (oldRank < 0 || oldRank >= 10)) {
                message = "You entered the top 10!";
            }
            if (message != null) {
                redis.convertAndSend("chan:notify:" + player,
                        json.writeValueAsString(new Notification(player, message, newRank + 1)));
            }
            redis.opsForStream().acknowledge(ScoreService.STREAM, GROUP, rec.getId());
        }
    }
}

package com.shopstream.leaderboard;

import java.nio.charset.StandardCharsets;
import java.time.Clock;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.connection.Message;
import org.springframework.data.redis.connection.RedisConnectionFactory;
import org.springframework.data.redis.listener.PatternTopic;
import org.springframework.data.redis.listener.RedisMessageListenerContainer;
@Configuration
public class PubSubConfig {

    @Bean
    Clock clock() {
        return Clock.systemDefaultZone();
    }

    @Bean
    RedisMessageListenerContainer listenerContainer(RedisConnectionFactory factory, SseHub hub) {
        var container = new RedisMessageListenerContainer();
        container.setConnectionFactory(factory);
        container.addMessageListener((Message message, byte[] pattern) -> {
            String channel = new String(message.getChannel(), StandardCharsets.UTF_8);
            String body = new String(message.getBody(), StandardCharsets.UTF_8);
            if (channel.equals("chan:board")) {
                hub.broadcast("leaderboard", body);
            } else if (channel.startsWith("chan:notify:")) {
                hub.sendTo(channel.substring("chan:notify:".length()), "notification", body);
            }
        }, new PatternTopic("chan:*"));
        return container;
    }
}

package com.shopstream.leaderboard;

import java.io.IOException;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;

/** Holds the SSE connections of THIS instance only. Other instances hold their own. */
@Component
public class SseHub {

    private record Subscriber(SseEmitter emitter, String player) {
    }

    private final List<Subscriber> subscribers = new CopyOnWriteArrayList<>();

    public SseEmitter subscribe(String player) {
        SseEmitter emitter = new SseEmitter(30 * 60 * 1000L);  // 30 min
        Subscriber s = new Subscriber(emitter, player);
        subscribers.add(s);
        emitter.onCompletion(() -> subscribers.remove(s));
        emitter.onTimeout(() -> subscribers.remove(s));
        emitter.onError(e -> subscribers.remove(s));
        send(s, "hello", "connected");                              // commits headers right away
        return emitter;
    }

    public void broadcast(String eventName, String data) {
        subscribers.forEach(s -> send(s, eventName, data));
    }

    public void sendTo(String player, String eventName, String data) {
        subscribers.stream().filter(s -> player.equals(s.player()))
                .forEach(s -> send(s, eventName, data));
    }

    public int connections() {
        return subscribers.size();
    }

    private void send(Subscriber s, String eventName, String data) {
        try {
            s.emitter().send(SseEmitter.event().name(eventName).data(data));
        } catch (IOException | IllegalStateException e) {
            subscribers.remove(s);                                  // client went away
        }
    }
}

