        return Map.of("uniquePlayersToday", scores.uniquePlayersToday());
    }

    @GetMapping(path = "/stream", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    public SseEmitter stream(@RequestParam(required = false) String player) {
        return hub.subscribe(player);
    }
}

