package com.shopstream.leaderboard;

import static org.assertj.core.api.Assertions.assertThat;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.List;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.annotation.Import;

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@Import(RedisTestConfig.class)
class LeaderboardIT {

    @Value("${local.server.port}") int port;
    @Autowired ScoreService scores;

    @Test
    void ranksFollowPointsAndReportOldAndNewRank() {
        scores.addPoints("t-ann", 100);
        scores.addPoints("t-ben", 300);
        var result = scores.addPoints("t-ann", 250);              // ann 350 passes ben 300
        assertThat(result.oldRank()).isGreaterThan(result.newRank());
        List<ScoreService.Entry> top = scores.top(100);
        int ann = top.stream().map(ScoreService.Entry::player).toList().indexOf("t-ann");
        int ben = top.stream().map(ScoreService.Entry::player).toList().indexOf("t-ben");
        assertThat(ann).isLessThan(ben);
        assertThat(scores.around("t-ann")).isPresent();
    }

    @Test
    void uniquePlayersCountsEachPlayerOnce() {
        long before = scores.uniquePlayersToday();
        scores.addPoints("t-u1", 1);
        scores.addPoints("t-u1", 1);
        scores.addPoints("t-u2", 1);
        assertThat(scores.uniquePlayersToday() - before).isEqualTo(2);
    }

    @Test
    void notificationReachesTheBrowserOverSse() throws Exception {
        HttpClient http = HttpClient.newHttpClient();
        BlockingQueue<String> lines = new LinkedBlockingQueue<>();
        HttpRequest sse = HttpRequest.newBuilder(
                URI.create("http://localhost:" + port + "/api/stream?player=sse-dana"))
                .header("Accept", "text/event-stream").build();
        http.sendAsync(sse, HttpResponse.BodyHandlers.ofLines())
                .thenAccept(r -> r.body().forEach(lines::add));
        assertThat(waitFor(lines, "data:connected")).isTrue();

        URI pointsUri = URI.create("http://localhost:" + port + "/api/points");
        HttpRequest post = HttpRequest.newBuilder(pointsUri)
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(
                        "{\"playerId\":\"sse-dana\",\"points\":9000}")).build();
        var response = http.send(post, HttpResponse.BodyHandlers.ofString());
        assertThat(response.statusCode()).isEqualTo(200);

        assertThat(waitFor(lines, "event:notification")).isTrue();
    }

    private static boolean waitFor(BlockingQueue<String> lines, String needle) throws Exception {
        long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
        while (System.nanoTime() < deadline) {
            String line = lines.poll(200, TimeUnit.MILLISECONDS);
            if (line != null && line.contains(needle)) {
                return true;
            }
        }
        return false;
    }
}
